    "big": "寺廟之美<br>趁著連續三天假期，爸爸帶我們到臺南市　北門區訪友，順便到知名古蹟、全國最大王爺廟――南鯤鯓　代天府拜拜。爸爸告訴我們，南鯤鯓　代天府香火鼎盛，已有悠久的歷史，是許多信眾祈求平安的重要場所。廟旁的槺榔山莊更有閩南傳統建築的美感，值得仔細欣賞。<br>才剛到廟前，莊嚴宏偉的牌樓就深深的吸引著我。高大的牌樓上布滿鮮豔的彩繪與細緻的裝飾，讓人還沒走進廟裡，就感受到古蹟的氣勢。在媽媽的帶領下，我們全家先到前殿向廟中供奉的五府千歲膜拜。香煙在空中緩緩上升，鐘鼓聲與人們低聲祈願的聲音交織在一起，使廟中的氣氛更加莊重。<br>趁著媽媽焚燒紙錢的同時，爸爸帶我和弟弟細細品味石壁上精美絕倫、栩栩如生的封神榜人物及走獸。那些人物有的神情威武，有的衣帶飄動，好像正從故事中走出來。石柱上的百雕，舉凡人物、花鳥、走獸，更是琳瑯滿目，美不勝收。<br>漫步在廟中，不論是頭頂的斗栱，還是腳邊的柱礎，細膩精美的雕工，總是讓我和弟弟驚呼不已。原來寺廟建築不只提供信眾祭拜，也保存許多傳統工藝。只要放慢腳步，就能在梁柱、屋簷與牆壁之間，看見前人對美感與信仰的用心。<br>走出寺廟，順著步道，我們來到了槺榔山莊。這是由數座閩南式四合院樓閣接合而成的建築，讓我們大開眼界。院落之間還有流水拱橋、假山垂柳，走在步道間，涼風徐徐吹來，爸爸笑著說，我們彷彿走進詩人的世界中。<br>這一次造訪南鯤鯓　代天府，讓我發現了寺廟的另一種美感。它不只是人們祈求平安的地方，也像一座保存歷史、信仰與藝術的文化寶庫。按下快門，我們在此地拍下了許多美麗的回憶，也把這份對傳統建築的驚喜留在心中。<br>【解釋】斗栱：栱，音ㄍㄨㄥˇ。斗栱是指梁柱間的銜接結構，功能在增加梁的承重量。<br>柱礎：墊在柱下的石頭。",
