    "big": "○月○日星期五　天氣：晴<br>國語課結束後，我跟好朋友筱晴對於公共藝術品分合隨緣的作者楊英風十分好奇，所以一起到圖書館查閱書籍。我們查到楊英風有一位很有名的學生――朱銘，這位聞名遐邇的藝術家，花費畢生精力創建了一座朱銘美術館來收藏他的作品，引發了我想去一探究竟的想法。<br>放學回家後，我跟家人討論明天去參觀朱銘美術館。家人同意之後，我上網查找資料，規劃前往美術館的路線，好期待明天就能出發！<br>○月○日星期六　天氣：雨<br>一大早，我們一家人搭乘公車抵達美術館。朱銘美術館就像一座綠化優美的公園，不僅在室內有展覽，在戶外也展示了銅塑及鋼塑的作品。我最喜歡的是太極系列的創作，並且從告示牌上讀到了朱銘的創作理念。我等不及趕快回到家中，將這兩天搜索到的資料整理成一份報告，下星期一就可以跟同學分享！",
