    "big": "衣錦還鄉<br>從學校騎腳踏車回家時，我發現鎮上的活動中心前掛滿了布條，路口還有志工忙著指引車輛。平常安靜的街道，今天顯得特別熱鬧。我滿心疑惑，回到家後立刻問媽媽：「今天鎮上有什麼大事嗎？怎麼到處都有人在準備活動？」<br>媽媽笑著說：「你沒看新聞嗎？在我們鎮上長大的林博士，得到國際獎項，今天回母校演講，晚上還要在活動中心接受表揚。大家都說，這可是他『衣錦還鄉』的日子呢！」<br>「衣錦還鄉？」我眼睛一亮，「今天老師剛好介紹過這個成語。它是形容人功成名就後，榮耀的回到故鄉，對不對？」<br>「沒錯。」媽媽推了推眼鏡，接著說：「你知道這個成語的由來嗎？」<br>我搖了搖頭，媽媽便說：「『衣錦』原本是指穿著華美的衣服，『還鄉』就是回到故鄉。這個成語和項羽有關。秦帝國滅亡後，有人勸項羽把都城設在關中，因為那裡地勢重要，適合建立基業。可是項羽一心想回到自己的故鄉，便說：『富貴不歸故鄉，如衣錦夜行。』意思是說，一個人功成名就後，如果不回到故鄉，就像穿著華美的衣服在夜裡行走，沒有人能看見自己的成就。」<br>媽媽又補充：「所以，『衣錦還鄉』後來就用來形容一個人有了成就後，風光的回到故鄉。像林博士離開家鄉多年，努力研究，得到國際肯定後再回來分享經驗，就很適合用這個成語。」<br>我想了想，又問：「可是，大家這麼熱烈歡迎他，會不會只是因為他現在有名了？」<br>媽媽說：「有時候，人的確容易對成功的人特別熱情。不過，如果大家是真心為家鄉出了一位優秀人才感到高興，也是一種『與有榮焉』。重要的是，我們不只得看見他的成功，也要看見他多年努力的過程。」",
