    "t": "閱讀測驗",
    "q": "長干行這首詩是用誰的口吻來描述？",
    "big": "青梅竹馬<br>一下課，就聽到宗維在哼一首老歌。歌裡唱著年少時的回憶，讓我忍不住問他：「你在唱什麼歌？」宗維笑著說：「這是我爸媽都很喜歡的一首歌，歌名叫青梅竹馬。」<br>我聽了更好奇：「我剛剛聽你唱的內容，好像沒有出現『青梅竹馬』這四個字，為什麼歌名要這樣取呢？」宗維不好意思的抓了抓頭髮說：「我唱的是副歌啦！我爸媽說，這首歌是在描寫年少時單純又難忘的感情，所以才用『青梅竹馬』當歌名。其實這個成語還有一段很有名的由來呢！」<br>「青梅竹馬」源自李白的長干行。李白是唐朝著名詩人，作品想像力豐富，情感奔放，後人稱他為「詩仙」。長干行是一首抒情敘事詩，詩中以一位年輕婦人的口吻，回憶自己從童年到婚後的生活，也寫出她對丈夫的思念。<br>詩中有幾句寫道：「妾髮初覆額，折花門前劇。郎騎竹馬來，遶床弄青梅。同居長干里，兩小無嫌猜。」意思是說，女子小時候頭髮剛剛蓋住額頭，常在門前折花玩耍；男孩騎著竹馬來到她身邊，繞著井欄玩青梅。他們同住在長干里，從小一起長大，彼此相處自然，沒有猜疑，也沒有隔閡。<br>從詩句可以看出，女子回想童年時，心中充滿懷念。那時的她和丈夫都還年幼，沒有複雜的想法，只是在門前玩耍、嬉戲，留下單純而美好的回憶。後來，「青梅竹馬」這個成語便從詩句中的「青梅」和「竹馬」演變而來，常用來比喻男女從小一起長大、感情親近；現在也可以泛指從小就相識的朋友。<br>聽完宗維介紹，我才明白，原來成語不只是幾個字而已，背後還可能藏著一首詩、一段故事和一種情感。難怪那首歌會用青梅竹馬當歌名，因為它想表達的正是年少時單純、珍貴又令人難忘的回憶。",
