    "q": "趙高為什麼要指著「鹿」說那是「馬」呢？",
    "big": "指鹿為馬<br>秦始皇統一天下後，建立了強大的帝國。可是他死後，宮廷中很快出現權力爭奪。宦官趙高為了掌握朝政，便和丞相李斯假傳聖旨，賜死秦始皇的長子扶蘇，改立年紀較小、容易控制的胡亥為皇帝。胡亥即位後，趙高的權勢越來越大，朝中許多大臣都十分害怕他。<br>後來，趙高當上丞相，大權在握，卻仍不滿足。他暗中想要奪取帝位，但又擔心朝中大臣不服從自己。為了試探眾人的態度，他想出一個荒謬的方法。有一天上朝時，趙高故意牽著一頭鹿走進宮殿，說：「陛下，臣獻上一匹好馬。」胡亥一看，忍不住笑說：「丞相弄錯了吧？這明明是一頭鹿，怎麼會是馬呢？」<br>趙高卻面不改色的回答：「這確實是一匹馬。若陛下不信，可以問問其他大臣。」胡亥便轉頭詢問群臣。大臣們心裡都知道那是一頭鹿，他們看趙高站在一旁，早就明白趙高的用意。有些人低下頭，不敢回答；有些人為了保住自己的官位，便附和趙高說：「這的確是一匹馬。」只有少數大臣堅持說實話，指出那是一頭鹿。<br>趙高藉這件事，看出哪些人順從自己，哪些人敢反對他。後來，那些說真話的大臣多半遭到趙高排擠或陷害，朝廷裡敢直言的人越來越少。胡亥聽見許多人都說鹿是馬，也開始懷疑自己的判斷，朝政便更加被趙高操控。<br>後來，「指鹿為馬」就從這段故事而來，比喻有權勢的人故意顛倒事實、混淆是非，甚至逼迫別人跟著說假話。這個故事也提醒我們，判斷事情不能只看有權勢的人怎麼說，也不能因為多數人附和，就把錯誤當成真相。面對是非對錯時，能保有清楚的判斷力與說真話的勇氣，才不會愧對良心。",
