    "t": "閱讀測驗",
    "q": "揚雄創作甘泉賦主要是想表達什麼？",
    "big": "雕蟲小技<br>揚雄是西漢時重要的文學家。他從小喜愛讀書，對寫文章也很有興趣。揚雄因為有口吃，說話比較慢，不擅長快速和別人爭辯，所以常常安靜的思考。他不貪圖權勢，也不追求名聲，即使生活貧困、家中糧食不足，仍然能安然自處，不因此感到煩惱。<br>揚雄非常仰慕古代聖賢，特別喜歡閱讀聖賢留下的書。他除了擅長當時相當受到重視，講究華麗文辭與鋪陳的辭賦以外，也努力向古代經典學習，曾模仿論語的形式寫成法言，又模仿易經的形式寫成太玄。<br>漢成帝前往甘泉宮時，揚雄也跟隨同行。當時皇帝出巡十分盛大，場面鋪張華麗，耗費不少人力物力，揚雄將這一切寫成了甘泉賦。這篇作品表面上描寫出巡的盛況，實際上是在勸諫漢成帝不要過度追求奢華。後來，他又創作長楊賦，同樣帶有勸誡意味，希望君王能重視國家大事，而不是沉迷於華貴享受。<br>有人問揚雄：「你年輕時是不是很喜歡寫辭賦？」揚雄回答：「是的。不過，這就像小孩子學習蟲書和刻符一樣，只是小小的技巧罷了。」當時學生會學習許多字體，其中蟲書和刻符很難書寫，須花費大量時間學習，但就算練成之後，也沒有太大的實際用途。因此，揚雄用它們來比喻自己年輕時喜愛的辭賦，認為那只是講究文字技巧的作品，不是胸懷大志的人應該追求的。<br>後來，「雕蟲小技」這個成語就從這段話演變而來，用來比喻微小、不值得誇耀的技能。有時候，人們也會用它來謙稱自己的文章或技藝。從揚雄的故事中，我們可以看出，他雖然擅長辭賦，卻不因此自滿，反而希望自己追求更深遠、更有意義的學問，如此精神，值得我們好好學習。",
